#include <vector>
#include <algorithm>

using namespace std;

class Solution {
public:
    int maxSatisfaction(vector<int>& satisfaction) {
        sort(satisfaction.rbegin(), satisfaction.rend());
        int total = 0, res = 0;
        for (int s : satisfaction) {
            total += s;
            if (total < 0) break;
            res += total;
        }
        return res;
    }
};
